#ifndef __PIPELINE_HPP__
#define __PIPELINE_HPP__

#include "hardware.hpp"
#include <memory>
#include <string>
#include <vector>

// ---- Module catalog and loading (src/model_loader.cpp) ----

// One candidate listed in build/modules/modules.json (generated by tool/build_modules.cmake).
struct ModuleInfo {
    std::string name;      // experiment folder name
    std::string kind;      // "joint" or "control"
    std::string directory; // repository-relative module folder
    std::string dll;       // absolute DLL path, empty when not runnable
    std::string assets;    // absolute assets folder
    bool runnable = false;
    bool adopted = false;  // selected in experiments/selected_modules.cmake
    std::string reason;    // why it is not runnable
};

std::vector<ModuleInfo> read_module_catalog(const std::string& modules_json);
const ModuleInfo& find_module(const std::vector<ModuleInfo>& catalog, const std::string& kind, const std::string& name);

struct Estimate {
    double y = 0, t = 0;
    bool measurement_valid = false;
    bool outside_training_range = false;
    double minimum_qr_correlation = 0, minimum_line_correlation = 0;
    std::string selected_axis, selected_branch;
    int tracked_points = 0, valid_points = 0;
    double model_cost = 0, other_axis_cost = 0, normalized_cost_margin = 0;
    double elapsed_ms = 0;
    std::string message;
};

// A loaded candidate DLL. Initialize once; do not share one instance between threads.
class Estimator {
public:
    explicit Estimator(const ModuleInfo& info);
    ~Estimator();
    Estimator(const Estimator&) = delete;
    Estimator& operator=(const Estimator&) = delete;
    Estimate estimate(const cv::Mat& image); // throws std::runtime_error with the module's reason
    const ModuleInfo& info() const;
private:
    struct Impl;
    std::unique_ptr<Impl> impl_;
};

// ---- Service rules (src/service_config.cpp, config/service.yml) ----

struct ServiceConfig {
    std::string profile;
    double tolerance = 0.09;
    double control_entry_t = 0.09;
    int max_iterations = 20;
    int max_capture_retries = 2;
    double move_fraction = 1.0;
    double sign_y = 0, sign_t = 0;         // must be +1 or -1
    double max_step_y = 0, max_step_t = 0; // 0 = unlimited
    double sim_tolerance_y = 0.025, sim_tolerance_t = 0.005;
};

// Throws when a value the team has not decided yet ("TBD") is required by the profile.
ServiceConfig load_service_config(const std::string& path, const std::string& profile);

// ---- Estimate -> motion command (src/command.cpp) ----

struct Command {
    double dy = 0, dt = 0;
    bool clipped = false;
};

Command t_command(const Estimate& estimate, const ServiceConfig& config);
Command y_command(const Estimate& estimate, const ServiceConfig& config);

// ---- Two-stage session (src/sequence.cpp) ----

enum class Stage { joint, control, done, failed };
const char* stage_name(Stage stage);

struct StepRecord {
    int index = 0;
    Stage stage = Stage::joint;  // stage that produced this step
    std::string module;
    std::string frame_source, frame_note;
    bool frame_simulated = false;
    bool pose_known = false;
    Pose pose_before, pose_after;
    bool estimated = false;
    Estimate estimate;
    std::string decision;
    bool moved = false;
    Command command;
    Stage next = Stage::joint;
};

// joint -> T move -> recapture -> control -> Y move -> recapture -> done (ALGORITHM_RULES 0.09).
// Call step() until finished(). Each call captures one frame and makes one decision.
class AlignmentSession {
public:
    AlignmentSession(Estimator& joint, Estimator& control, ICamera& camera, IRobot& robot, ServiceConfig config);
    StepRecord step();
    bool finished() const;
    Stage stage() const;
    const std::string& failure() const;
    const std::vector<StepRecord>& records() const;
    std::string to_json() const;
private:
    Estimator& joint_;
    Estimator& control_;
    ICamera& camera_;
    IRobot& robot_;
    ServiceConfig config_;
    Stage stage_ = Stage::joint;
    int failures_in_row_ = 0;
    std::string failure_;
    std::vector<StepRecord> records_;
};

#endif // __PIPELINE_HPP__
